{"command":"cat << 'EOF' > src/infrastructure/logging.rs
use std::fs::{self, File, OpenOptions};
use std::io::Write;
use std::path::PathBuf;
use std::sync::Mutex;
use chrono::Utc;

pub struct FileLogger {
    file: Mutex<Option<File>>,
}

static LOGGER: FileLogger = FileLogger {
    file: Mutex::new(None),
};

pub fn init_logging() -> Option<PathBuf> {
    let home = dirs::home_dir()?;
    let log_dir = home.join(".gittype").join("logs");
    if fs::create_dir_all(&log_dir).is_err() {
        return None;
    }

    let timestamp = Utc::now().format("%Y%m%d_%H%M%S").to_string();
    let log_path = log_dir.join(format!("gittype_{}.log", timestamp));

    if let Ok(file) = OpenOptions::new().create(true).append(true).open(&log_path) {
        if let Ok(mut guard) = LOGGER.file.lock() {
            *guard = Some(file);
        }
    }

    log_info("gittype::infrastructure::logging", &format!("GitType logging initialized, logs saved to: {}", log_dir.to_string_lossy()));
    Some(log_dir)
}

pub fn log_info(module: &str, msg: &str) {
    write_log("INFO", module, msg);
}

pub fn log_warn(module: &str, msg: &str) {
    write_log("WARN", module, msg);
}

pub fn log_error(module: &str, msg: &str) {
    write_log("ERROR", module, msg);
}

fn write_log(level: &str, module: &str, msg: &str) {
    let now = Utc::now().format("%Y-%m-%d %H:%M:%S").to_string();
    let line = format!("{} [{}] {} - {}\n", now, level, module, msg);

    if let Ok(mut guard) = LOGGER.file.lock() {
        if let Some(file) = guard.as_mut() {
            let _ = file.write_all(line.as_bytes());
        }
    }
}
EOF"}

