                    let name = CStr::from_ptr(*col_names.add(i)).to_string_lossy();
                    let val_ptr = *col_values.add(i);
                    let val = if val_ptr.is_null() {
                        ""
                    } else {
                        CStr::from_ptr(val_ptr).to_str().unwrap_or("")
                    };

                    match name.as_ref() {
                        "id" => id = val.parse::<i64>().ok(),
                        "user_name" => user_name = val.to_string(),
                        "repository_name" => repo_name = val.to_string(),
                        "remote_url" => remote_url = val.to_string(),
                        "created_at" => created_at = Some(val.to_string()),
                        _ => {}
                    }
                }

                ctx.repos.push(Repository {
                    id,
                    user_name,
                    repository_name: repo_name,
                    remote_url,
                    created_at,
                });
            }
            0
        }

        let mut ctx = CallbackCtx { repos: Vec::new() };
        let sql = CString::new("SELECT id, user_name, repository_name, remote_url, created_at FROM repositories").unwrap();
        let mut errmsg: *mut c_char = std::ptr::null_mut();

        unsafe {
            let rc = sqlite3_exec(
                self.db_ptr,
                sql.as_ptr(),
                Some(callback),
                &mut ctx as *mut CallbackCtx as *mut c_void,
                &mut errmsg,
            );
            if rc != 0 {
                let err = if !errmsg.is_null() {
                    let s = CStr::from_ptr(errmsg).to_string_lossy().to_string();
                    sqlite3_free(errmsg as *mut c_void);
                    s
                } else {
                    format!("Error code {}", rc)
                };
                return Err(GitTypeError::DatabaseError(err));
            }
        }

        Ok(ctx.repos)
    }
}

impl Drop for Database {
    fn drop(&mut self) {
        if !self.db_ptr.is_null() {
            unsafe {
                sqlite3_close(self.db_ptr);
            }
        }
    }
}
