use std::fs;
use std::path::PathBuf;
use crate::domain::error::GitTypeError;

pub fn get_cache_dir() -> Option<PathBuf> {
    let home = dirs::home_dir()?;
    let dir = home.join(".gittype").join("cache");
    let _ = fs::create_dir_all(&dir);
    Some(dir)
}

pub fn stats() -> Result<(), GitTypeError> {
    let mut count = 0;
    let mut total_bytes: u64 = 0;

    if let Some(dir) = get_cache_dir() {
        if let Ok(entries) = fs::read_dir(dir) {
            for entry in entries.flatten() {
                if let Ok(metadata) = entry.metadata() {
                    if metadata.is_file() {
                        count += 1;
                        total_bytes += metadata.len();
                    } else if metadata.is_dir() {
                        count += 1;
                        if let Ok(sub_entries) = fs::read_dir(entry.path()) {
                            for sub in sub_entries.flatten() {
                                if let Ok(m) = sub.metadata() {
                                    total_bytes += m.len();
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    println!("Challenge Cache Statistics:");
    println!("  Cached repositories: {}", count);
    println!("  Total size: {} bytes", total_bytes);
    Ok(())
}

pub fn clear() -> Result<(), GitTypeError> {
    if let Some(dir) = get_cache_dir() {
        if let Ok(entries) = fs::read_dir(&dir) {
            for entry in entries.flatten() {
                let _ = fs::remove_dir_all(entry.path()).or_else(|_| fs::remove_file(entry.path()));
            }
        }
    }
    println!("Challenge cache cleared successfully.");
    Ok(())
}

pub fn list() -> Result<(), GitTypeError> {
    let mut keys = Vec::new();
    if let Some(dir) = get_cache_dir() {
        if let Ok(entries) = fs::read_dir(dir) {
            for entry in entries.flatten() {
                if let Ok(ft) = entry.file_type() {
                    let name = entry.file_name().to_string_lossy().to_string();
                    if ft.is_file() {
                        if let Some(stem) = name.strip_suffix(".bin").or_else(|| name.strip_suffix(".json")) {
                            keys.push(stem.to_string());
                        }
                    } else if ft.is_dir() {
                        keys.push(name);
                    }
                }
            }
        }
    }

    if keys.is_empty() {
        println!("No cached challenges found.");
    } else {
        for key in keys {
            println!("- {}", key);
        }
    }
    Ok(())
}
EOF"}

