use std::fs;
use std::io::{self, Write};
use std::path::PathBuf;
use crate::domain::error::GitTypeError;

pub fn get_repos_dir() -> Option<PathBuf> {
    let home = dirs::home_dir()?;
    Some(home.join(".gittype").join("repos"))
}

pub fn count_cached_repos() -> usize {
    let mut count = 0;
    if let Some(repos_dir) = get_repos_dir() {
        if repos_dir.exists() {
            fn check_dir(dir: &PathBuf, count: &mut usize) {
                if let Ok(entries) = fs::read_dir(dir) {
                    for entry in entries.flatten() {
                        let path = entry.path();
                        if path.is_dir() {
                            if path.join(".git").exists() {
                                *count += 1;
                            } else {
                                check_dir(&path, count);
                            }
                        }
                    }
                }
            }
            check_dir(&repos_dir, &mut count);
        }
    }
    count
}

pub fn repo_clear(force: bool) -> Result<(), GitTypeError> {
    let repos_dir = match get_repos_dir() {
        Some(d) => d,
        None => {
            println!("No cached repositories directory found.");
            return Ok(());
        }
    };

    if !repos_dir.exists() {
        println!("No cached repositories directory found.");
        return Ok(());
    }

    let count = count_cached_repos();
    if count == 0 {
        println!("No cached repositories found.");
        return Ok(());
    }

    if !force {
        println!("This will delete all locally cached repositories in:");
        println!("  {}", repos_dir.display());
        println!("({} cached repositories will be removed)", count);
        print!("Are you sure you want to continue? [y/N]: ");
        let _ = io::stdout().flush();

        let mut input = String::new();
        if io::stdin().read_line(&mut input).is_ok() {
            let trimmed = input.trim().to_lowercase();
            if trimmed != "y" && trimmed != "yes" {
                println!("Operation cancelled.");
                return Ok(());
            }
        } else {
            println!("Operation cancelled.");
            return Ok(());
        }
    }

    let _ = fs::remove_dir_all(&repos_dir);
    println!("Successfully deleted all cached repositories.");
    println!("Cache directory {} has been removed.", repos_dir.display());
    Ok(())
}
