            | "rb" | "php" | "swift" | "kt" | "hs" | "dart" | "scala" | "zig"
    )
}

pub fn extract_challenges(repo_path: &Path, lang_filter: Option<&[String]>) -> Vec<Challenge> {
    let mut challenges = Vec::new();
    if !repo_path.exists() {
        return challenges;
    }

    for entry in WalkDir::new(repo_path)
        .into_iter()
        .filter_entry(|e| {
            let name = e.file_name().to_string_lossy();
            !name.starts_with('.') && name != "target" && name != "node_modules" && name != "vendor"
        })
        .flatten()
    {
        if entry.file_type().is_file() {
            let path = entry.path();
            if let Some(ext) = path.extension().and_then(|s| s.to_str()) {
                if is_supported_extension(ext) {
                    let lang_name = ext.to_lowercase();
                    if let Some(filter) = lang_filter {
                        if !filter.iter().any(|f| f.to_lowercase() == lang_name) {
                            continue;
                        }
                    }

                    if let Ok(content) = fs::read_to_string(path) {
                        let rel_path = path.strip_prefix(repo_path).unwrap_or(path).to_string_lossy().to_string();
                        let file_challenges = parse_code_blocks(&rel_path, &lang_name, &content);
                        challenges.extend(file_challenges);
                    }
                }
            }
        }
    }

    challenges
}

fn parse_code_blocks(file_path: &str, language: &str, content: &str) -> Vec<Challenge> {
    let mut challenges = Vec::new();
    let lines: Vec<&str> = content.lines().collect();
    if lines.is_empty() {
        return challenges;
    }

    let mut current_block = Vec::new();
    let mut start_line = 1;

    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            if current_block.len() >= 3 {
                let code_content = current_block.join("\n");
                let char_count = code_content.len();
                let diff = if char_count < 150 {
                    DifficultyLevel::Easy
                } else if char_count <= 300 {
                    DifficultyLevel::Normal
                } else {
                    DifficultyLevel::Hard
                };

                challenges.push(Challenge {
                    id: format!("{}_{}_{}", file_path, start_line, i),
                    file_path: file_path.to_string(),
                    start_line,
                    end_line: i,
                    language: language.to_string(),
                    code_content,
                    difficulty_level: diff.name().to_string(),
                });
            }
            current_block.clear();
            start_line = i + 2;
        } else {
            if current_block.is_empty() {
                start_line = i + 1;
            }
            current_block.push(*line);
        }
    }

    if current_block.len() >= 3 {
        let code_content = current_block.join("\n");
        let char_count = code_content.len();
        let diff = if char_count < 150 {
            DifficultyLevel::Easy
        } else if char_count <= 300 {
            DifficultyLevel::Normal
        } else {
            DifficultyLevel::Hard
        };

        challenges.push(Challenge {
            id: format!("{}_{}_{}", file_path, start_line, lines.len()),
            file_path: file_path.to_string(),
            start_line,
            end_line: lines.len(),
            language: language.to_string(),
            code_content,
            difficulty_level: diff.name().to_string(),
        });
    }

    challenges
}
EOF"}

