use std::process::exit;
use clap::ArgMatches;
use crate::infrastructure::{cache, git};
use crate::presentation::tui::screen_manager::{run_screen_manager, AppMode};

pub fn handle_cli(matches: &ArgMatches, raw_args: &[String]) {
    match matches.subcommand() {
        Some(("history", _)) => {
            eprintln!("❌ History command is not yet implemented");
            eprintln!("💡 This feature is planned for a future release");
            exit(1);
        }
        Some(("stats", _)) => {
            eprintln!("❌ Stats command is not yet implemented");
            eprintln!("💡 This feature is planned for a future release");
            exit(1);
        }
        Some(("export", sub_m)) => {
            let format = sub_m.get_one::<String>("format").map(|s| s.as_str()).unwrap_or("json");
            eprintln!("❌ Export command is not yet implemented");
            eprintln!("💡 Requested format: {}", format);
            if let Some(output) = sub_m.get_one::<String>("output") {
                eprintln!("💡 Requested output: {}", output);
            }
            eprintln!("💡 This feature is planned for a future release");
            exit(1);
        }
        Some(("cache", sub_m)) => {
            match sub_m.subcommand() {
                Some(("stats", _)) => {
                    let _ = cache::stats();
                }
                Some(("clear", _)) => {
                    let _ = cache::clear();
                }
                Some(("list", _)) => {
                    let _ = cache::list();
                }
                _ => {
                    let _ = cache::stats();
                }
            }
        }
        Some(("repo", sub_m)) => {
            match sub_m.subcommand() {
                Some(("clear", sub_sub_m)) => {
                    let force = sub_sub_m.get_flag("force");
                    let _ = git::repo_clear(force);
                }
                Some(("list", _)) => {
                    run_tui_app(AppMode::RepoList, raw_args);
                }
                Some(("play", _)) => {
                    run_tui_app(AppMode::RepoList, raw_args);
                }
                _ => {
                    run_tui_app(AppMode::RepoList, raw_args);
                }
            }
        }
        Some(("trending", sub_m)) => {
            let lang = sub_m.get_one::<String>("LANGUAGE").cloned();
            let repo = sub_m.get_one::<String>("REPO_NAME").cloned();
            if let Some(l) = lang {
                run_tui_app(AppMode::TrendingRepoSelection(l, repo), raw_args);
            } else {
                run_tui_app(AppMode::TrendingLangSelection, raw_args);
            }
        }
        _ => {
            // Default game mode
            let repo_path = matches.get_one::<String>("REPO_PATH").cloned();
            let repo_url = matches.get_one::<String>("repo").cloned();
            let langs = matches.get_one::<String>("langs").cloned();

            let target_path = repo_path.unwrap_or_else(|| ".".to_string());
            run_tui_app(AppMode::Game { target_path, repo_url, langs }, raw_args);
        }
    }
}

fn run_tui_app(mode: AppMode, raw_args: &[String]) {
    if let Err(e) = run_screen_manager(mode) {
        e.write_error_log(raw_args);
        exit(1);
    }
}
EOF"}

