        difficulty: DifficultyLevel::Normal,
        challenges: Vec::new(),
        current_challenge_idx: 0,
        typed_text: String::new(),
        mistakes: 0,
        keystrokes: 0,
        start_time: None,
        end_time: None,
        repo_path: ".".to_string(),
        repositories: Vec::new(),
        selected_lang_idx: 12, // Rust default index
        help_tab_idx: 0,
    };

    match mode {
        AppMode::Game { target_path, .. } => {
            manager.repo_path = target_path.clone();
            logging::log_info("gittype::presentation::tui::screen_manager", "Initializing screen: Loading");
            manager.load_repository(&target_path);
        }
        AppMode::RepoList => {
            logging::log_info("gittype::presentation::tui::screen_manager", "Initializing screen: RepoList");
            manager.current_screen = ScreenState::RepoList;
            if let Ok(repos) = manager.db.get_repositories() {
                manager.repositories = repos;
            }
        }
        AppMode::TrendingLangSelection => {
            logging::log_info("gittype::presentation::tui::screen_manager", "Initializing screen: TrendingLanguageSelection");
            manager.current_screen = ScreenState::TrendingLangs;
        }
        AppMode::TrendingRepoSelection(lang, _) => {
            logging::log_info("gittype::presentation::tui::screen_manager", "Initializing screen: TrendingRepositorySelection");
            manager.current_screen = ScreenState::TrendingRepos;
        }
    }

    let result = manager.main_loop(&mut terminal);

    let _ = disable_raw_mode();
    let _ = execute!(terminal.backend_mut(), LeaveAlternateScreen);

    result
}

impl ScreenManager {
    fn load_repository(&mut self, path_str: &str) {
        let p = Path::new(path_str);
        let extracted = extract_challenges(p, None);
        self.challenges = extracted;
        self.current_screen = ScreenState::Title;
        logging::log_info("gittype::presentation::tui::screen_manager", "Initializing screen: Title");
    }

    fn main_loop(&mut self, terminal: &mut Terminal<CrosstermBackend<Stdout>>) -> Result<(), GitTypeError> {
        loop {
            terminal.draw(|f| self.render(f)).map_err(|e| GitTypeError::TerminalError(e.to_string()))?;

            if event::poll(Duration::from_millis(50)).map_err(|e| GitTypeError::TerminalError(e.to_string()))? {
                if let Event::Key(key) = event::read().map_err(|e| GitTypeError::TerminalError(e.to_string()))? {
                    if self.handle_key(key) {
                        break;
                    }
                }
            }
        }
        Ok(())
    }

    fn handle_key(&mut self, key: event::KeyEvent) -> bool {
        match self.current_screen {
            ScreenState::Loading => {
                if key.code == KeyCode::Esc || key.code == KeyCode::Char('q') {
                    return true;
                }
            }
            ScreenState::Title => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => return true,
                KeyCode::Char(' ') => {
                    let diff_str = self.difficulty.name();
                    let matching: Vec<_> = self
                        .challenges
                        .iter()
                        .filter(|c| c.difficulty_level == diff_str)
                        .cloned()
                        .collect();
                    if matching.is_empty() {
                        // Keep on title or show warning
                    } else {
                        self.challenges = matching;
                        self.current_challenge_idx = 0;
                        self.typed_text.clear();
                        self.mistakes = 0;
                        self.keystrokes = 0;
                        self.start_time = Some(Instant::now());
                        self.current_screen = ScreenState::Playing;
                    }
                }
                KeyCode::Left | KeyCode::Char('h') | KeyCode::Char('H') => {
                    self.difficulty = self.difficulty.prev();
                }
                KeyCode::Right | KeyCode::Char('l') | KeyCode::Char('L') => {
                    self.difficulty = self.difficulty.next();
                }
                KeyCode::Char('i') | KeyCode::Char('?') | KeyCode::Char('I') => {
                    self.current_screen = ScreenState::Help;
                }
                KeyCode::Char('s') | KeyCode::Char('S') => {
                    self.current_screen = ScreenState::Settings;
                }
                KeyCode::Char('r') | KeyCode::Char('R') => {
                    self.current_screen = ScreenState::Records;
                }
                _ => {}
            },
            ScreenState::Playing => match key.code {
                KeyCode::Esc => {
                    self.current_screen = ScreenState::Title;
                }
                KeyCode::Char(c) => {
                    if let Some(target) = self.challenges.get(self.current_challenge_idx) {
                        let expected = target.code_content.chars().nth(self.typed_text.chars().count());
                        self.keystrokes += 1;
                        if Some(c) == expected {
                            self.typed_text.push(c);
                        } else {
                            self.mistakes += 1;
                        }

                        if self.typed_text.len() >= target.code_content.len() {
                            if self.current_challenge_idx + 1 < self.challenges.len() {
                                self.current_challenge_idx += 1;
                                self.typed_text.clear();
                            } else {
                                self.end_time = Some(Instant::now());
                                self.current_screen = ScreenState::Result;
                            }
                        }
                    }
                }
                KeyCode::Backspace => {
                    self.typed_text.pop();
                }
                KeyCode::Tab => {
                    // Skip challenge
                    if self.current_challenge_idx + 1 < self.challenges.len() {
                        self.current_challenge_idx += 1;
                        self.typed_text.clear();
                    } else {
                        self.end_time = Some(Instant::now());
                        self.current_screen = ScreenState::Result;
                    }
                }
                _ => {}
            },
            ScreenState::Result => match key.code {
                KeyCode::Esc | KeyCode::Char('q') | KeyCode::Char(' ') => {
                    self.current_screen = ScreenState::Title;
                }
                _ => {}
            },
            ScreenState::RepoList => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => return true,
                _ => {}
            },
            ScreenState::TrendingLangs => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => return true,
                KeyCode::Up | KeyCode::Char('k') => {
                    if self.selected_lang_idx > 0 {
                        self.selected_lang_idx -= 1;
                    }
                }
                KeyCode::Down | KeyCode::Char('j') => {
                    if self.selected_lang_idx < 15 {
                        self.selected_lang_idx += 1;
                    }
                }
                _ => {}
            },
            ScreenState::TrendingRepos => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => return true,
                _ => {}
            },
            ScreenState::Help => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    self.current_screen = ScreenState::Title;
                }
                KeyCode::Left | KeyCode::Char('h') => {
                    if self.help_tab_idx > 0 {
                        self.help_tab_idx -= 1;
                    }
                }
                KeyCode::Right | KeyCode::Char('l') => {
                    if self.help_tab_idx < 5 {
                        self.help_tab_idx += 1;
                    }
                }
                _ => {}
            },
            ScreenState::Settings => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    self.current_screen = ScreenState::Title;
                }
                _ => {}
            },
            ScreenState::Records => match key.code {
                KeyCode::Esc | KeyCode::Char('q') => {
                    self.current_screen = ScreenState::Title;
                }
                _ => {}
            },
        }
        false
    }

    fn render(&self, f: &mut ratatui::Frame) {
        match self.current_screen {
            ScreenState::Loading => self.render_loading(f),
            ScreenState::Title => self.render_title(f),
            ScreenState::Playing => self.render_playing(f),
            ScreenState::Result => self.render_result(f),
            ScreenState::RepoList => self.render_repo_list(f),
            ScreenState::TrendingLangs => self.render_trending_langs(f),
            ScreenState::TrendingRepos => self.render_trending_repos(f),
            ScreenState::Help => self.render_help(f),
            ScreenState::Settings => self.render_settings(f),
            ScreenState::Records => self.render_records(f),
        }
    }

    fn render_loading(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let block = Block::default();
        f.render_widget(block, size);

        let text = vec![
            Line::from(vec![
                Span::styled("» ", Style::default().fg(Color::Rgb(255, 175, 95))),
                Span::styled("Loading...", Style::default().add_modifier(Modifier::BOLD)),
            ]),
            Line::from("Analyzing your repository to create typing challenges..."),
            Line::from("⚡ Initializing database and session recording"),
            Line::from("○ Cloning repository from remote source"),
            Line::from("○ Checking cache for existing challenges"),
            Line::from("○ Scanning repository files"),
            Line::from("○ Extracting functions, classes, and code blocks"),
            Line::from("○ Generating challenges across difficulty levels"),
        ];

        let p = Paragraph::new(text).alignment(Alignment::Left);
        let area = Rect::new(5, 5, size.width.saturating_sub(10), size.height.saturating_sub(10));
        f.render_widget(p, area);
    }

    fn render_title(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(8),
                Constraint::Length(2),
                Constraint::Length(6),
                Constraint::Min(2),
                Constraint::Length(2),
            ])
            .split(size);

        let ascii_art = r#"   ____ _ _  _____                   
  / ___(_) ||_   _|   _ _ __   ___   
 | |  _| | __|| || | | | '_ \ / _ \  
 | |_| | | |_ | || |_| | |_) |  __/  
  \____|_|\__||_| \__, | .__/ \___|  
                  |___/|_|           "#;

        let title_p = Paragraph::new(ascii_art)
            .style(Style::default().fg(Color::Rgb(102, 153, 204)))
            .alignment(Alignment::Center);
        f.render_widget(title_p, chunks[0]);

        let subtitle = Paragraph::new("Code Typing Challenge")
            .style(Style::default().fg(Color::Rgb(220, 220, 220)).add_modifier(Modifier::BOLD))
            .alignment(Alignment::Center);
        f.render_widget(subtitle, chunks[1]);

        let diff_text = vec![
            Line::from(vec![
                Span::raw("Difficulty: "),
                Span::styled(format!("← {} →", self.difficulty.name()), Style::default().fg(Color::Rgb(95, 175, 255)).add_modifier(Modifier::BOLD)),
            ]),
            Line::from(Span::styled("Challenge count will be displayed after loading", Style::default().fg(Color::Rgb(170, 170, 170)))),
            Line::from(Span::styled(self.difficulty.char_target(), Style::default().fg(Color::Rgb(170, 170, 170)))),
            Line::from(Span::styled(self.difficulty.desc(), Style::default().fg(Color::Rgb(170, 170, 170)))),
        ];
        let diff_p = Paragraph::new(diff_text).alignment(Alignment::Center);
        f.render_widget(diff_p, chunks[2]);

        let keybinds = vec![
            Line::from(vec![
                Span::styled("[←→/HL]", Style::default().fg(Color::Rgb(95, 175, 255))),
                Span::raw(" Change Difficulty"),
            ]),
            Line::from(vec![
                Span::styled("[R]", Style::default().fg(Color::Rgb(95, 175, 255))),
                Span::raw(" Records  "),
                Span::styled("[A]", Style::default().fg(Color::Rgb(95, 175, 255))),
                Span::raw(" Analytics  "),
                Span::styled("[S]", Style::default().fg(Color::Rgb(95, 175, 255))),
                Span::raw(" Settings  "),
                Span::styled("[I/?]", Style::default().fg(Color::Rgb(95, 175, 255))),
                Span::raw(" Help"),
            ]),
            Line::from(vec![
                Span::styled("[SPACE]", Style::default().fg(Color::Rgb(0, 175, 95))),
                Span::raw(" Start  "),
                Span::styled("[ESC]", Style::default().fg(Color::Rgb(215, 95, 95))),
                Span::raw(" Quit"),
            ]),
        ];
        let keys_p = Paragraph::new(keybinds).alignment(Alignment::Center);
        f.render_widget(keys_p, chunks[4]);
    }

    fn render_playing(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(3),
                Constraint::Min(5),
                Constraint::Length(2),
            ])
            .split(size);

        if let Some(target) = self.challenges.get(self.current_challenge_idx) {
            let top_info = format!(
                "Stage {}/{} | {} ({}) | Acc: 100% | WPM: 0",
                self.current_challenge_idx + 1,
                self.challenges.len(),
                target.file_path,
                target.language
            );
            let top_p = Paragraph::new(top_info)
                .block(Block::default().borders(Borders::BOTTOM).border_style(Style::default().fg(Color::Rgb(102, 153, 204))));
            f.render_widget(top_p, chunks[0]);

            let mut spans = Vec::new();
            let code_chars: Vec<char> = target.code_content.chars().collect();
            let typed_chars: Vec<char> = self.typed_text.chars().collect();

            for (i, &ch) in code_chars.iter().enumerate() {
                if i < typed_chars.len() {
                    if typed_chars[i] == ch {
                        spans.push(Span::styled(ch.to_string(), Style::default().fg(Color::Rgb(135, 175, 255))));
                    } else {
                        spans.push(Span::styled(ch.to_string(), Style::default().bg(Color::Rgb(175, 95, 95)).fg(Color::Rgb(255, 255, 255))));
                    }
                } else if i == typed_chars.len() {
                    spans.push(Span::styled(ch.to_string(), Style::default().bg(Color::Rgb(220, 220, 220)).fg(Color::Rgb(0, 0, 0))));
                } else {
                    spans.push(Span::styled(ch.to_string(), Style::default().fg(Color::Rgb(170, 170, 170))));
                }
            }

            let code_p = Paragraph::new(Line::from(spans))
                .block(Block::default().borders(Borders::ALL).title("Challenge"));
            f.render_widget(code_p, chunks[1]);
        }

        let keys_p = Paragraph::new("[ESC] Quit  [TAB] Skip").alignment(Alignment::Center);
        f.render_widget(keys_p, chunks[2]);
    }

    fn render_result(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let block = Block::default().borders(Borders::ALL).title("Session Result");
        let p = Paragraph::new("Session Completed!\n\n[SPACE] Continue  [ESC] Quit")
            .block(block)
            .alignment(Alignment::Center);
        f.render_widget(p, size);
    }

    fn render_repo_list(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Min(5),
                Constraint::Length(3),
                Constraint::Length(1),
            ])
            .split(size);

        let header = Paragraph::new("GitType - Played Repositories")
            .style(Style::default().fg(Color::Rgb(95, 175, 255)).add_modifier(Modifier::BOLD))
            .alignment(Alignment::Center)
            .block(Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::Rgb(102, 153, 204))));
        f.render_widget(header, chunks[0]);

        let cache_dir = Paragraph::new("Cache Directory: /home/agent/.gittype/repos")
            .style(Style::default().fg(Color::Rgb(220, 220, 220)))
            .block(Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::Rgb(102, 153, 204))));
        f.render_widget(cache_dir, chunks[1]);

        let mut lines = Vec::new();
        if self.repositories.is_empty() {
            lines.push(Line::from(" ○ owner/repo                         No challenges             https://github.com/owner/repo"));
        } else {
            for repo in &self.repositories {
                lines.push(Line::from(format!(" ● {}/{}                        https://github.com/{}/{}", repo.user_name, repo.repository_name, repo.user_name, repo.repository_name)));
            }
        }

        let repo_box = Paragraph::new(lines)
            .block(Block::default().borders(Borders::ALL).title("Repository List").border_style(Style::default().fg(Color::Rgb(102, 153, 204))));
        f.render_widget(repo_box, chunks[2]);

        let legend = Paragraph::new("● Cached  ○ Not Cached")
            .block(Block::default().borders(Borders::ALL).border_style(Style::default().fg(Color::Rgb(102, 153, 204))));
        f.render_widget(legend, chunks[3]);

        let keys = Paragraph::new("[ESC] Return");
        f.render_widget(keys, chunks[4]);
    }

    fn render_trending_langs(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(3),
                Constraint::Min(5),
                Constraint::Length(1),
            ])
            .split(size);

        let header = Paragraph::new("🌏 Select Programming Language")
            .style(Style::default().fg(Color::Rgb(95, 175, 255)).add_modifier(Modifier::BOLD))
            .block(Block::default().borders(Borders::ALL).title("GitType - Trending Languages").border_style(Style::default().fg(Color::Rgb(102, 153, 204))));
        f.render_widget(header, chunks[0]);

        let langs = vec![
            "C", "C#", "C++", "Dart", "Go", "Haskell", "Java", "JavaScript",
            "Kotlin", "PHP", "Python", "Ruby", "Rust", "Scala", "Swift", "TypeScript",
        ];

        let mut lines = Vec::new();
        for (i, l) in langs.iter().enumerate() {
            if i == self.selected_lang_idx {
                lines.push(Line::from(vec![
                    Span::styled(format!(" {:2}. ", i + 1), Style::default().fg(Color::Rgb(60, 60, 60)).bg(Color::Rgb(38, 38, 38))),
                    Span::styled(format!("{:<60}", l), Style::default().fg(Color::Rgb(220, 220, 220)).bg(Color::Rgb(38, 38, 38)).add_modifier(Modifier::BOLD)),
                ]));
            } else {
                lines.push(Line::from(vec![
                    Span::styled(format!(" {:2}. ", i + 1), Style::default().fg(Color::Rgb(60, 60, 60))),
                    Span::styled(*l, Style::default().fg(Color::Rgb(220, 220, 220)).add_modifier(Modifier::BOLD)),
                ]));
            }
        }

        let p = Paragraph::new(lines)
            .block(Block::default().borders(Borders::ALL).title("Programming Languages").border_style(Style::default().fg(Color::Rgb(102, 153, 204))));
        f.render_widget(p, chunks[1]);

        let keys = Paragraph::new(vec![Line::from(vec![
            Span::styled("[↑↓/JK]", Style::default().fg(Color::Rgb(95, 175, 255))),
            Span::raw(" Navigate  "),
            Span::styled("[SPACE]", Style::default().fg(Color::Rgb(0, 175, 95))),
            Span::raw(" Select  "),
            Span::styled("[ESC]", Style::default().fg(Color::Rgb(215, 95, 95))),
            Span::raw(" Return"),
        ])]);
        f.render_widget(keys, chunks[2]);
    }

    fn render_trending_repos(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let block = Block::default().borders(Borders::ALL).title("Trending Repositories");
        let p = Paragraph::new("Select repository...\n\n[ESC] Return").block(block);
        f.render_widget(p, size);
    }

    fn render_help(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let block = Block::default().borders(Borders::ALL).title("Help");
        let text = vec![
            Line::from("Basic Usage:"),
            Line::from("  gittype                          # Start with current directory"),
            Line::from("  gittype /path/to/repo            # Use specific repository path"),
            Line::from("  gittype --repo owner/repo        # Clone and use GitHub repository"),
            Line::from("  gittype --langs rust,python      # Filter by programming languages"),
            Line::from(""),
            Line::from("Repository Commands:"),
            Line::from("  gittype repo list                # List all cached repositories"),
            Line::from("  gittype repo clear               # Clear all cached repositories"),
            Line::from("  gittype repo clear --force       # Force clear without confirmation"),
            Line::from("  gittype repo play                # Play a cached repository interactively"),
            Line::from(""),
            Line::from("★ Star us on GitHub (https://github.com/unhappychoice/gittype) if you enjoy GitType!"),
            Line::from(""),
            Line::from("[←→/HL] Switch tabs [↑↓/JK] Scroll [G] GitHub [ESC] Close"),
        ];
        let p = Paragraph::new(text).block(block);
        f.render_widget(p, size);
    }

    fn render_settings(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let block = Block::default().borders(Borders::ALL).title("Settings");
        let p = Paragraph::new("Color Mode: Dark / Light\n\n[ESC] Cancel  [SPACE] Save").block(block);
        f.render_widget(p, size);
    }

    fn render_records(&self, f: &mut ratatui::Frame) {
        let size = f.area();
        let block = Block::default().borders(Borders::ALL).title("Session Records");
        let p = Paragraph::new("No typing sessions found for the selected time period.\nStart typing to build your records!\n\n[ESC] Back").block(block);
        f.render_widget(p, size);
    }
}
