use thiserror::Error;

#[allow(dead_code)]
#[derive(Error, Debug)]
pub enum GitTypeError {
    #[error("Terminal error: {0}")]
    TerminalError(String),

    #[error("Database error: {0}")]
    DatabaseError(String),

    #[error("Git error: {0}")]
    GitError(String),

    #[error("Cache error: {0}")]
    CacheError(String),

    #[error("Failed to extract code chunks: {0}")]
    ExtractionError(String),

    #[error("IO error: {0}")]
    IoError(String),

    #[error("{0}")]
    Generic(String),
}

impl GitTypeError {
    pub fn write_error_log(&self, args: &[String]) {
        let now = chrono::Utc::now();
        let timestamp_file = now.format("%Y%m%d_%H%M%S").to_string();
        let timestamp_log = now.format("%Y-%m-%d %H:%M:%S UTC").to_string();
        let filename = format!("gittype_error_{}.log", timestamp_file);

        let cwd = std::env::current_dir()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|_| "unknown".to_string());
        let exe = std::env::current_exe()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_else(|_| "unknown".to_string());

        let args_json = serde_json::to_string(args).unwrap_or_else(|_| "[]".to_string());

        let content = format!(
            "ERROR OCCURRED AT: {}\nERROR TYPE: \"gittype::domain::error::GitTypeError\"\nERROR MESSAGE: {}\nEXECUTABLE: \"{}\"\nWORKING_DIR: \"{}\"\nCOMMAND_ARGS: {}\nOS: linux\nARCH: x86_64\n\n",
            timestamp_log, self, exe, cwd, args_json
        );

        let _ = std::fs::write(&filename, &content);
        eprintln!("💾 Error details written to: {}", filename);
        eprintln!("Error: {}", self);
    }
}
EOF"}

